<?php
require_once __DIR__.'/../app.php';require_once __DIR__.'/../ui.php';require_once __DIR__.'/../backup_service.php';require_admin();
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    verify_csrf();try{
        $action=request_string($_POST,'action');
        if($action==='download_sql'){$content=database_backup();save_private_backup($content,'sql');audit('backup_database','backups',null,'Created and downloaded database data backup');header('Content-Type: application/sql');header('Content-Disposition: attachment; filename="backup_'.date('Ymd_His').'.sql"');echo $content;exit;}
        if(in_array($action,['download_application','download_files'],true)){$kind=$action==='download_files'?'files':'application';$path=create_file_backup($kind);audit('backup_files','backups',null,'Created and downloaded '.$kind.' backup');header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="backup_'.$kind.'_'.date('Ymd_His').'.zip"');header('Content-Length: '.filesize($path));readfile($path);exit;}
        if($action==='preview'){
            $f=$_FILES['backup']??null;$ext=strtolower(pathinfo($f['name']??'',PATHINFO_EXTENSION));if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>25*1024*1024||!is_uploaded_file($f['tmp_name'])||!in_array($ext,['sql','zip'],true))throw new DomainException('Select an application SQL or ZIP backup no larger than 25 MB.');
            $content=file_get_contents($f['tmp_name']);$path=save_private_backup($content,$ext);$payload=$ext==='sql'?parse_database_backup($content):stage_file_backup($path);$_SESSION['restore_preview']=['kind'=>$ext,'path'=>$path,'sha256'=>hash('sha256',$content),'manifest'=>$payload['manifest'],'stage'=>$ext==='zip'?$payload:null,'token'=>bin2hex(random_bytes(16)),'created'=>time()];audit('restore_preview','backups',null,'Validated restoration preview');redirect('backup.php');
        }
        if($action==='restore'){
            $p=$_SESSION['restore_preview']??null;if(!$p||time()-$p['created']>900||!hash_equals($p['token'],request_string($_POST,'token'))||request_string($_POST,'confirm')!=='RESTORE'||!hash_equals($p['sha256'],hash_file('sha256',$p['path'])))throw new DomainException('Type RESTORE and use a valid preview no older than 15 minutes.');
            if($p['kind']==='sql'){restore_database(parse_database_backup(file_get_contents($p['path'])));$_SESSION=[];session_regenerate_id(true);flash('success','Database restored and verified. Previous sessions have been invalidated. A recovery backup was preserved.');redirect('login.php');}
            apply_staged_files($p['stage']);remove_staging_directory($p['stage']['directory']);unset($_SESSION['restore_preview']);flash('success','Files restored and verified. Previous file versions are preserved in private recovery storage.');redirect('backup.php');
        }
        throw new DomainException('Unknown backup action.');
    }catch(DomainException $e){flash('danger',$e->getMessage());}
}
page_start('Backup and restore','Administrator-only backups, validation previews, and recoverable restoration.');
?><div class="two-column"><section class="panel"><h2>Create a backup</h2><p>SQL contains application data for schema version 002. Keep schema.sql and the application source for disaster recovery.</p><form method="post" class="button-stack"><?php csrf_field();?><button class="btn btn-primary" name="action" value="download_sql">Backup database (.sql)</button><button class="btn btn-outline-primary" name="action" value="download_application">Backup application & assets (.zip)</button><button class="btn btn-outline-primary" name="action" value="download_files">Backup uploaded documents (.zip)</button></form><p class="small text-secondary mt-3">External production credentials and runtime secrets are excluded. Source restoration is performed offline through the documented CLI. Backup copies are stored outside the public application directory.</p><?php if(!class_exists('ZipArchive'))echo '<div class="alert alert-warning">Enable the PHP zip extension for ZIP operations.</div>';?></section><section class="panel"><h2>Validate a backup</h2><form method="post" enctype="multipart/form-data" class="form-grid"><?php csrf_field();input_field('backup','Application SQL or file-only ZIP (max 25 MB)','','file',true,'accept=".sql,.zip"');?><button class="btn btn-outline-primary" name="action" value="preview">Validate and preview</button></form><p class="small text-secondary mt-3">SQL restores replace all application data. Uploaded-file restores accept only supported images, PDFs, and text files. A full source archive cannot be restored through the browser.</p></section></div>
<?php $p=$_SESSION['restore_preview']??null;if($p):?><section class="panel"><h2>Restoration preview</h2><p>Archive created <?=h($p['manifest']['created_at'])?> · schema <?=h($p['manifest']['schema'])?></p><?php if($p['kind']==='sql'){$summary=[];foreach($p['manifest']['tables']as $table=>$m)$summary[]=['table'=>$table,'count'=>$m['count']];data_table($summary,['table'=>'Table','count'=>'Rows']);}else{$summary=[];foreach($p['manifest']['files']as $path=>$m)$summary[]=['path'=>$path,'size'=>$m['size']];data_table($summary,['path'=>'File','size'=>'Bytes']);}?><div class="alert alert-warning">Confirm only after reviewing this preview. Current data/files will be replaced. Recovery copies will be retained.</div><form method="post" class="form-grid" data-confirm="Restore this backup and replace the current data/files?"><?php csrf_field();?><input type="hidden" name="token" value="<?=h($p['token'])?>"><?php input_field('confirm','Type RESTORE');?><button class="btn btn-danger" name="action" value="restore">Confirm restoration</button></form></section><?php endif;page_end();
